const fs = require('fs');
const path = require('path');

// Helper to generate slug
function slugify(text) {
  return text.toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

const rawModels = [];

function addModel(brand, brandSlug, series, model, category, wifiStandard, speedRating, ports, throughput, os, useCase, ip, username, password, loginUrl, features) {
  const modelSlug = slugify(`${brand} ${model}`);
  rawModels.push({
    brand,
    brandSlug,
    model,
    slug: modelSlug,
    series: series || `${brand} Networking`,
    category,
    wifiStandard,
    speedRating: speedRating || 'Gigabit Class',
    ports,
    throughput: throughput || 'Full Line-Rate Gigabit Switching',
    os: os || `${brand} OS`,
    useCase,
    ip: ip || '192.168.1.1',
    protocol: 'HTTP/HTTPS',
    username: username || 'admin',
    password: password || 'admin',
    loginUrl: loginUrl || `http://${ip || '192.168.1.1'}`,
    features: features || ['Dual Band', 'Gigabit Ethernet', 'WPA3 Security', 'IPv6 Support']
  });
}

